# Initialize SwaggerSchemaValidator
validator = SwaggerSchemaValidator(API_SPEC_PATH)

@pytest.mark.parametrize("scenario_case", _PARAM_CASES, ids=_PARAM_IDS)
def test_update_user(api_client, host, config_test_data, scenario_case):
    """
    Test the update user endpoint using various scenarios defined in the JSON data.
    """
    # Prepare endpoint and payload
    endpoint = API_ENDPOINT.format(username=scenario_case["username"])
    payload = {
        "id": scenario_case["id"],
        "username": scenario_case["username"]
    }
    # Optional fields
    if "firstName" in scenario_case:
        payload["firstName"] = scenario_case["firstName"]
    if "lastName" in scenario_case:
        payload["lastName"] = scenario_case["lastName"]
    if "email" in scenario_case:
        payload["email"] = scenario_case["email"]
    if "password" in scenario_case:
        payload["password"] = scenario_case["password"]
    if "phone" in scenario_case:
        payload["phone"] = scenario_case["phone"]
    if "userStatus" in scenario_case:
        payload["userStatus"] = scenario_case["userStatus"]

    # Validate payload before sending
    validate_request = validator.validate_json(payload, "User")
    assert validate_request["valid"], f"Request validation failed: {validate_request.get('message')}"

    # Execute API request
    headers = {"Authorization": f"Bearer {config_test_data['petstore_auth']}"}
    response = api_client.put(endpoint, headers=headers, data=json.dumps(payload))

    # Validate response status code
    expected_status_code = scenario_case["statusCode"]
    assert response.status_code == expected_status_code, f"Unexpected status code: {response.status_code}"

